use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
fn run_interactive_mode (target_dir : & str) -> Result < () > { println ! ("🎯 Interactive Syscall Oracle Mode") ; println ! ("==================================") ; loop { println ! ("\n🛡️ Available commands:") ; println ! ("  1. Transform with mock mode") ; println ! ("  2. Transform with strict type safety") ; println ! ("  3. Transform with DAO governance") ; println ! ("  4. Analyze syscalls in directory") ; println ! ("  5. Generate oracle types") ; println ! ("  6. Exit") ; print ! ("\nEnter choice (1-6): ") ; std :: io :: Write :: flush (& mut std :: io :: stdout ()) ? ; let mut input = String :: new () ; std :: io :: stdin () . read_line (& mut input) ? ; match input . trim () { "1" => { transform_directory (target_dir , "mock_wrapped" , true , "strict" , false) ? ; } "2" => { transform_directory (target_dir , "type_safe_wrapped" , false , "strict" , false) ? ; } "3" => { transform_directory (target_dir , "dao_governed_wrapped" , false , "paranoid" , true) ? ; } "4" => { analyze_syscalls (target_dir , true) ? ; } "5" => { generate_oracle_code ("interactive_oracles.rs") ? ; } "6" => { println ! ("👋 Goodbye!") ; break ; } _ => { println ! ("❌ Invalid choice, please enter 1-6") ; } } } Ok (()) }
}